import zipfile
import json
import re
import os

# Load JSON
with open('/root/supplier_contact.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# Flatten nested JSON
def flatten(obj, prefix=''):
    items = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_key = f"{prefix}{k}" if not prefix else f"{prefix}.{k}"
            if isinstance(v, (dict, list)):
                items.update(flatten(v, new_key))
            else:
                items[new_key] = str(v)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            new_key = f"{prefix}[{i}]"
            if isinstance(v, (dict, list)):
                items.update(flatten(v, new_key))
            else:
                items[new_key] = str(v)
    return items

flat = flatten(data)
# Also keep top-level keys as-is
if isinstance(data, dict):
    for k, v in data.items():
        if not isinstance(v, (dict, list)):
            flat[k] = str(v)

print("Replacement map:")
for k, v in flat.items():
    print(f"  {{{{{k}}}}} -> {v}")

# Process HWPX
src = '/root/supplier_contact_template.hwpx'
dst = '/root/supplier_contact_ready.hwpx'

with zipfile.ZipFile(src, 'r') as zin, zipfile.ZipFile(dst, 'w', zipfile.ZIP_DEFLATED) as zout:
    for item in zin.infolist():
        raw = zin.read(item.filename)
        try:
            text = raw.decode('utf-8')
            modified = False
            for key, val in flat.items():
                placeholder = '{{' + key + '}}'
                if placeholder in text:
                    text = text.replace(placeholder, val)
                    modified = True
            # Remove stale layout cache from modified paragraphs
            if modified:
                text = re.sub(r'<hp:lineSegArray>.*?</hp:lineSegArray>', '', text, flags=re.DOTALL)
            zout.writestr(item, text)
        except (UnicodeDecodeError, Exception):
            zout.writestr(item, raw)

# Verify no placeholders remain
print("\nVerification:")
remaining = []
with zipfile.ZipFile(dst, 'r') as z:
    for name in z.namelist():
        try:
            content = z.read(name).decode('utf-8')
            found = re.findall(r'\{\{[^}]+\}\}', content)
            if found:
                remaining.extend([(name, p) for p in found])
                print(f"  WARNING: {name} still has: {found}")
        except:
            pass

if remaining:
    print(f"FAIL: {len(remaining)} placeholders remain!")
